      "supporting_evidence": [
        "Cough with purulent (‘mucky’) phlegm.",
        "Subjective fever with chills/night sweats.",
        "Increasing dyspnoea.",
        "Risk factors: Type 2 DM, smoker, male age 50."
      ],
      "opposing_evidence": [
        "No pleuritic chest pain.",
        "No objective fever, tachypnoea, or abnormal lung exam documented.",
        "Runny nose and sore throat more typical of URI."
      ]
